/**
 * Definition for a binary tree node. public class TreeNode { int val; TreeNode left; TreeNode
 * right; TreeNode() {} TreeNode(int val) { this.val = val; } TreeNode(int val, TreeNode left,
 * TreeNode right) { this.val = val; this.left = left; this.right = right; } }
 */
class Solution {
  public TreeNode sufficientSubset(TreeNode root, int limit) {
    TreeNode dummy = new TreeNode(0);
    dummy.left = root;
    helper(dummy, 0, limit);
    return dummy.left;
  }

  public int helper(TreeNode root, int sum, int limit) {
    if (root == null) return 0;
    sum += root.val;

    int left = helper(root.left, sum, limit);
    int right = helper(root.right, sum, limit);

    int pathSum =
        root.left == null && root.right == null
            ? 0
            : Math.max(
                root.left == null ? Integer.MIN_VALUE : left,
                root.right == null ? Integer.MIN_VALUE : right);

    if (left + sum < limit) root.left = null;
    if (right + sum < limit) root.right = null;

    return pathSum + root.val;
  }
}
